use crate::common;
use rust_xlsxwriter::{Image, Workbook, XlsxError};

// Create a rust_xlsxwriter file to compare against an Excel file.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let red = Image::new("tests/input/images/red.png")?.set_alt_text("red.png");
    let blue = Image::new("tests/input/images/blue.png")?;

    // An image on a worksheet before the embedded image shouldn't affect the
    // embedded image's cell metadata index or its image file.
    let worksheet1 = workbook.add_worksheet();
    worksheet1.insert_image(8, 4, &red)?;

    let worksheet2 = workbook.add_worksheet();
    worksheet2.embed_image(0, 0, &blue)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_embed_image14() {
    let test_runner = common::TestRunner::new()
        .set_name("embed_image14")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
